import{_ as a,o as e,c as t,aj as r}from"./chunks/framework.BdtAaXf2.js";const p="/assets/image-20250722072751352.Cw9xGbE1.png",i="/assets/image-20250722074951115.B8VYZSzh.png",s="/assets/image-20250722080239722.DTJQaMxq.png",o="/assets/abc.BAPGjQq6.png",l="/assets/image-20250722102348731.Zw31kQ2s.png",h="/assets/image-20250622200325374.BLr7GNE1.png",m="/assets/image-20250722100717843.21U64oy7.png",b=JSON.parse('{"title":"2025 鸿蒙创新赛又来了，万少教你如何强势切入","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/2025 鸿蒙创新赛又来了，万少教你如何强势切入/2025 鸿蒙创新赛又来了，万少教你如何强势切入.md","filePath":"鸿蒙开发技巧/2025 鸿蒙创新赛又来了，万少教你如何强势切入/2025 鸿蒙创新赛又来了，万少教你如何强势切入.md","lastUpdated":1756109794000,"__rawMarkdown":"# 2025 鸿蒙创新赛又来了，万少教你如何强势切入\\n\\n## 前言\\n\\n​\\t2025 华为[HarmonyOS 创新赛](https://developer.huawei.com/consumer/cn/activity/digixActivity/digixcmsdetail/101750143863263087?ha_source=51CTOpo&ha_sourceId=89000408)又来了，创新赛是鸿蒙生态最大规模开发者官方赛事，最高获百万激励。\\n\\n![一图胜千言](assets/image-20250722072751352.png)\\n\\n## 参赛资格\\n\\n1. 面向所有开发者开放\\n2. 以队伍的形式来参加，可以一个人报名一个队伍，也可以多个人在一个队伍。\\n\\n\\n\\n\\n\\n## 我也可以吗\\n\\n参赛的队伍性质，大概可以分为两类\\n\\n1. 企业\\n2. 个人\\n\\n### 企业\\n\\n​\\t企业的性质一般是站在**公司产品**、战略角度所开发的APP，这一类项目由企业做为绝对的主导，一般的开发者负责参与其中即可，这种情况需要企业负责人多想想如何开发出一款优秀的应用，这就需要结合实际的情况、公司的投入等等来考量了，但是不可否认的是有想要开发鸿蒙产品的公司，确实需要利用好这一个赛事来提速自己的产品，毕竟给的奖励还是不少的。\\n\\n### 个人\\n\\n​\\t**这个是这一个文章的重点**，因为大多或多的程序员朋友都还有一个做产品的梦想，但是受限制于各种条件：时间、创意、技术、坚持等等导致自己的项目**流产**了。那么，程序员朋友想要开发一个鸿蒙应用的作品具体该怎么进行呢，这里我们先分享一下开发鸿蒙APP的流程。\\n\\n\\n\\n## 鸿蒙APP 和 鸿蒙元服务 的备案、软著解读\\n\\n![image-20250722074951115](assets/image-20250722074951115.png)\\n\\n参考以上流程，我们不难得出以下总结\\n\\n1. **开发单机的元服务和开发单机的APP**：流程是最简单的，不需要备案、也不需要软著。比如我开发一个单机的图片压缩工具，它使用内置的鸿蒙API便可以完成全部功能，不需要登录、不需要联网。\\n2. **开发联网的元服务**：联网的元服务，就需要对元服务进行备案了，备案需要有服务器、域名，这个过程需要经过工信部审核的，流程2-5天左右，你可以选择腾讯云、阿里云、华为云等这些云资源。备案是必须的！。\\n3. **开发联网的APP**：如果是开发APP，那么除了备案你的APP之外，还需要进行软著的申请，软著有免费流程也有收费流程，慢的话就一个月，快的话一或两个星期内完成。\\n\\n\\n\\n## 一款产品需要的配套技术\\n\\n![image-20250722080239722](assets/image-20250722080239722.png)\\n\\n如上图，根据开发的作品的选型不同，所涉及到的配套技术也不一样\\n\\n1. **开发一款微信：** 由于微信是一个必须要联网，而且业务复杂度巨大的产品，那么只能选择**传统后端**的配套环境，自己买服务器、数据库、云存储等资源，由专门的后端来开发响应的接口，提供服务。\\n2. **开发一款读书APP**：读书APP的核心功能相对来说业务复杂度降低了很多，只需要提供基本的书籍类的资讯数据即可，加不加用户账户功能都可以考量取舍的，这类的业务可以使用**端云一体**的技术，降低了服务器运维等相关繁琐的工作，**这一类app是偏向查询类的业务，新增、修改、删除功能几乎 没有**。\\n3. **开发一款天气应用**：天气应用可以不接入登录，就只对接第三方天气接口，等于是只有查询功能，没有新增、修改、删除功能。\\n\\n\\n\\n## 总结\\n\\n​\\t可以看到，如果想要开发一个质量还不错的应用，对于一般的 开发者，尤其是前端开发者来讲，难度还是巨大的！所以，针对这个情况，这一类开发者只有一个解决方案，那么就是抱大腿！抱大腿！抱大腿！抱大腿！抱大腿！抱大腿！抱大腿！\\n\\n![img](assets/abc.png)\\n\\n​\\t找到合适的队伍或者组织或者大佬，抱着他大腿，你拥有了大腿，等于就拥有了大腿的人脉、资源圈。\\n\\n\\n\\n**我的队伍**：\\n\\n![image-20250722102348731](assets/image-20250722102348731.png)\\n\\n\\n\\n\\n\\n\\n\\n## 关于我们\\n\\n\\n\\n\\n\\n### 组织信息\\n\\n\\n\\n[关于青蓝逐码组织](https://link.juejin.cn/?target=https%3A%2F%2Fwww.qinglanzhuma.cn%2F)\\n\\n如果你兴趣想要了解更多的鸿**蒙应用开发细节和最新资讯**，**甚至你想要做出一款属于自己的应用**！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n![image-20250622200325374](assets/image-20250622200325374.png)\\n\\n---\\n\\n### 上架作品\\n\\n![image-20250722100717843](assets/image-20250722100717843.png)\\n\\n---\\n\\n### 过往文章\\n\\n- [第五款 HarmonyOS 上架作品 奇趣故事匣 来了](https://mp.weixin.qq.com/s/l-p25xQxHjdjhhmKkziaTQ)\\n- [我们又来啦 又又上架了一个鸿蒙项目-萤火故事屋](https://mp.weixin.qq.com/s/_fjKN9_Qje2fsFEfNlRw7A)\\n- [我们又上架了一个鸿蒙项目-止欲](https://mp.weixin.qq.com/s/zALYRljZC0d3vzfzTW9sGg)\\n- [孵化两个上线项目-谈一谈最近的近况](https://mp.weixin.qq.com/s/DTL5M8yYwK5ajeVhqsOyMA)\\n\\n\\n\\n\\n\\n## 附录\\n\\n### 评审规则\\n\\n比赛的评选机制包含一般奖项和专项奖评审标准。\\n\\n1.一般奖项（特等奖、一等奖、二等奖、三等奖）：总分100分=创新性（50分）+完备度（30分）+价值性（20）\\n\\n（1)创新性（50分）：在HarmonyOS相关技术的基础上，有技术、设计等方面创新点，满足行业的发展趋势，解决现有痛点问题，富有突破性、具有产业标杆效应。项目所涉及的创新特性应为本次大赛过程中产出。\\n\\n（2）完备度（30分）：具备作品所涉及的所有核心功能，在功能、稳定性、用户体验和提交材料等方面完备，复杂功能可只完成可行性验证。\\n\\n（3）价值性（20）：\\n\\n①商业价值（10）：有明确的市场定位和目标用户，有可行性的商业计划，有清晰的可持续的盈利模式。\\n\\n②社会价值（10）：创造积极的社会影响，推动行业进步，包括但不限于医疗健康、教育科普、经济发展、环境保护、公益援助、提升社会资源效率，或有助于解决广泛性社会问题。\\n\\n2、专项奖：\\n\\n（1）AI智能创新奖：\\n\\n基于小艺智能体开放平台，运用大模型、工作流、插件、知识库、记忆等能力，开发具有创新、易用和好用的智能体，必须上架。\\n\\n评分标准：创新性（40）+用户体验（30）+功能完备度（30分）\\n\\n最佳创新奖（专项奖）：3个\\n\\n最具人气奖（专项奖）：3个\\n\\n越用越智能奖（专项奖）：4个\\n\\n（2）游戏创新奖：\\n\\n游戏创新奖：鼓励广大游戏开发者基于HarmonyOS系统的一多适配、碰一碰等创新特性进行游戏开发，为玩家提供玩法更新颖、体验更沉浸的游戏作品。（不强制要求作品在参赛期间上架）\\n\\n评分标准：创新玩法（40分）+技术深度（40分）+美术表现（20分）。在满足至少调用3个创新Kit的基础上，其中每接入一个游戏相关的创新Kit加5分，最多加20分。\\n\\n最佳跨端游戏奖：2个\\n\\n创意玩法突破奖：2个\\n\\n最佳视觉艺术奖：2个\\n\\n潜力新星游戏奖：2个\\n\\n优秀叙事表达奖：2个\\n\\n（3）最具社会价值奖：\\n\\n在解决社会广泛关注的问题价值突出的优秀作品（社会价值分）；范围：所有参赛作品。\\n\\n评分标准：社会问题解决价值（60分）+用户体验与影响力（20分）+作品实现度（20分）\\n\\n最具社会价值奖：10个\\n\\n（4）场景创新奖：\\n\\n作品创意主题不限，可涵盖但不限于智能化、多设备协同、空间化、潮流玩法、社交创新、折叠屏适配、移动轻办公、无障碍等领域，参赛者可自由命题。\\n\\n鼓励参赛者结合超级终端、原生智能等HarmonyOS系统特性，以及基于折叠屏、穿戴设备等新设备形态进行创新创意命题。\\n\\n要求提交实际应用演示Demo、创意描述、设计稿和介绍文档。\\n\\n作品评分标准：创新性（50分）+完备度（20分）+前景评估（20分）+文档质量（10分）\\n\\n场景创新奖：10个\\n\\n（5）元服务创新奖\\n\\n参赛者需调用元服务有价值的开放能力和工具。\\n\\n①开放能力五个：服务通知、服务动态、支付服务、地图、扫码；工具：ASCF；\\n\\n②要求元服务真实可用，需完成上架；\\n\\n评分标准：创新性（40分）+技术深度（40分）+用户体验与设计（20分）\\n\\n元服务创新奖：20个\\n\\n（6）校园星火奖\\n\\n校园开发者个人/团队参与开发的优秀应用；申请该奖项的需在大赛页面补充需提交学生身份证明。\\n\\n鼓励学生快速了解鸿蒙生态并开发鸿蒙应用，突出创新潜力，降低门槛，无需上架应用。\\n\\n评审标准：创新性（50分）+鸿蒙技术性（30分）+作品完成度（20分）\\n\\n校园星火奖：30个\\n\\n（7）桃李领航奖：\\n\\n协调高校资源，指导团队制定开发计划，帮助团队顺利完成优秀应用；申请该奖项的需在大赛页面补充需提交教师身份证明。\\n\\n激励教师组织学生参与，扩大赛事覆盖面。\\n\\n评审标准：招募学生/团队规模（50分）+组织成效（30分）+资源整合（20分）。\\n\\n桃李领航奖：30个"}'),g={name:"鸿蒙开发技巧/2025 鸿蒙创新赛又来了，万少教你如何强势切入/2025 鸿蒙创新赛又来了，万少教你如何强势切入.md"};function c(_,n,d,P,q,u){return e(),t("div",null,[...n[0]||(n[0]=[r("",88)])])}const A=a(g,[["render",c]]);export{b as __pageData,A as default};
